import { z } from 'zod';

/**
 * Typed environment (ARCHITECTURE.md §5, §11). Validated once at startup; the process exits
 * with a list of the offending keys (never their values) when anything is wrong.
 *
 * Adapters: only the demo implementations exist so far. Each production implementation is
 * added to its enum in the milestone that builds it (S3 storage, SMTP mailer, ClamAV, Redis).
 */
const DEMO_ADAPTERS = {
  STORAGE_ADAPTER: 'local',
  MAILER_ADAPTER: 'console',
  MALWARE_SCANNER: 'noop',
  RATE_LIMIT_STORE: 'memory',
  JOB_QUEUE: 'manual',
} as const;

/** Keys generated by `pnpm setup:dev` carry this key-ID prefix; production refuses them. */
export const DEV_KEY_PREFIX = 'dev-';

const KEY_ID = z
  .string()
  .regex(/^[A-Za-z0-9._-]{1,64}$/, 'must be a key ID (letters, digits, . _ -)');

/** Base64 value that must decode to at least `minBytes` bytes. */
const base64Secret = (minBytes: number) =>
  z
    .string()
    .regex(/^[A-Za-z0-9+/_-]+={0,2}$/, 'must be base64')
    .transform((value) => Buffer.from(value, 'base64'))
    .refine((bytes) => bytes.length >= minBytes, `must decode to at least ${minBytes} bytes`);

/** Base64-encoded PEM (keeps multi-line PEM keys on one .env line). */
const base64Pem = (label: string) =>
  z
    .string()
    .transform((value) => Buffer.from(value, 'base64').toString('utf8'))
    .refine(
      (pem) => pem.includes(`-----BEGIN ${label}-----`),
      `must be a base64-encoded ${label} PEM`,
    );

/** "id:base64key,id:base64key" — AES-256 keys (32 bytes) by key ID, for rotation. */
const fieldKeys = z.string().transform((value, ctx) => {
  const keys: Record<string, Buffer> = {};
  for (const entry of value
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)) {
    const [id, material] = entry.split(':');
    const bytes = material ? Buffer.from(material, 'base64') : Buffer.alloc(0);
    if (!id || !KEY_ID.safeParse(id).success || bytes.length !== 32) {
      ctx.addIssue({
        code: 'custom',
        message: 'each entry must be "<keyId>:<base64 32-byte key>"',
      });
      return z.NEVER;
    }
    keys[id] = bytes;
  }
  return keys;
});

export const envSchema = z
  .object({
    NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
    API_PORT: z.coerce.number().int().min(1).max(65535).default(4000),
    WEB_ORIGIN: z
      .string()
      .min(1)
      .transform((value) => value.split(',').map((origin) => origin.trim()))
      .pipe(z.array(z.url())),
    LOG_LEVEL: z
      .enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace', 'silent'])
      .default('info'),
    DATABASE_URL: z
      .string()
      .regex(/^postgres(ql)?:\/\//, 'must be a postgresql:// connection string'),
    STORAGE_ADAPTER: z.enum(['local']).default('local'),
    /** Where the local storage adapter keeps uploaded files (relative to the repository root). */
    STORAGE_DIR: z.string().min(1).default('storage'),
    MAILER_ADAPTER: z.enum(['console']).default('console'),
    MALWARE_SCANNER: z.enum(['noop']).default('noop'),
    RATE_LIMIT_STORE: z.enum(['memory']).default('memory'),
    /**
     * Multiplies every rate limit. 1 everywhere people use the app; the browser test suite sets
     * it higher, because it signs in dozens of times a minute from one address. Must be 1 in
     * production.
     */
    RATE_LIMIT_SCALE: z.coerce.number().int().min(1).max(100).default(1),
    /** pgboss: jobs run on schedule (ADR 0003). manual: only when triggered (tests, tools). */
    JOB_QUEUE: z.enum(['pgboss', 'manual']).default('pgboss'),

    // Identity (M1)
    /** Public origin of the web app; used in links sent by email. */
    APP_BASE_URL: z.url().default('http://localhost:3001'),
    /** Where the console mailer writes emails (relative to the repository root). */
    MAIL_OUTBOX_DIR: z.string().min(1).default('outbox'),
    JWT_PRIVATE_KEY: base64Pem('PRIVATE KEY'),
    JWT_PUBLIC_KEY: base64Pem('PUBLIC KEY'),
    JWT_KEY_ID: KEY_ID,
    /** HMAC key for storing refresh/email tokens and recovery codes as keyed hashes. */
    TOKEN_HASH_KEY: base64Secret(32),
    FIELD_ENCRYPTION_KEYS: fieldKeys,
    FIELD_ENCRYPTION_KEY_ID: KEY_ID,

    // Passkeys (M1b). Default to the web app's host and origin (APP_BASE_URL).
    /** WebAuthn relying-party ID: the site's domain (e.g. "localhost", "connect.example.org"). */
    WEBAUTHN_RP_ID: z
      .string()
      .regex(/^[a-z0-9.-]+$/, 'must be a domain name without scheme or port')
      .optional(),
    /** Origin(s) the browser reports during passkey ceremonies, comma-separated. */
    WEBAUTHN_ORIGIN: z
      .string()
      .transform((value) => value.split(',').map((origin) => origin.trim()))
      .pipe(z.array(z.url()))
      .optional(),
  })
  .transform(({ WEBAUTHN_RP_ID, WEBAUTHN_ORIGIN, ...env }) => {
    const base = new URL(env.APP_BASE_URL);
    return {
      ...env,
      WEBAUTHN_RP_ID: WEBAUTHN_RP_ID ?? base.hostname,
      WEBAUTHN_ORIGIN: WEBAUTHN_ORIGIN ?? [base.origin],
    };
  })
  .superRefine((env, ctx) => {
    if (!(env.FIELD_ENCRYPTION_KEY_ID in env.FIELD_ENCRYPTION_KEYS)) {
      ctx.addIssue({
        code: 'custom',
        path: ['FIELD_ENCRYPTION_KEY_ID'],
        message: 'must name one of the keys in FIELD_ENCRYPTION_KEYS',
      });
    }
    if (env.NODE_ENV !== 'production') return;
    if (env.WEBAUTHN_RP_ID === 'localhost') {
      ctx.addIssue({
        code: 'custom',
        path: ['WEBAUTHN_RP_ID'],
        message: 'passkeys need the real domain in production, not localhost',
      });
    }
    if (env.RATE_LIMIT_SCALE !== 1) {
      ctx.addIssue({
        code: 'custom',
        path: ['RATE_LIMIT_SCALE'],
        message: "rate limits can't be scaled in production",
      });
    }
    for (const key of ['JWT_KEY_ID', 'FIELD_ENCRYPTION_KEY_ID'] as const) {
      if (env[key].startsWith(DEV_KEY_PREFIX)) {
        ctx.addIssue({
          code: 'custom',
          path: [key],
          message: 'development keys are not allowed in production',
        });
      }
    }
    for (const [key, demoValue] of Object.entries(DEMO_ADAPTERS)) {
      if (env[key as keyof typeof DEMO_ADAPTERS] === demoValue) {
        ctx.addIssue({
          code: 'custom',
          path: [key],
          message: `demo adapter "${demoValue}" is not allowed in production`,
        });
      }
    }
  });

export type Env = z.output<typeof envSchema>;

export class InvalidEnvironmentError extends Error {
  constructor(readonly problems: string[]) {
    super(`Invalid environment configuration:\n  - ${problems.join('\n  - ')}`);
    this.name = 'InvalidEnvironmentError';
  }
}

/** Parses the environment. Error messages name the key and the rule, never the value. */
export function parseEnv(source: Record<string, string | undefined>): Env {
  const result = envSchema.safeParse(source);
  if (result.success) return result.data;
  const problems = result.error.issues.map(
    (issue) => `${issue.path.join('.') || '(root)'}: ${issue.message}`,
  );
  throw new InvalidEnvironmentError(problems);
}
